import sys
class Element:
    def __init__(self, ident, events): self.ident, self.events = ident, events
    def click(self): self.events.append(f'click:{self.ident}')
class Driver:
    def __init__(self): self.events = []; self.closed = False
    def find_element(self, selector):
        if selector not in {'[data-testid=save]', '[data-testid=cancel]'}: raise LookupError(selector)
        return Element(selector, self.events)
    def quit(self): self.closed = True
def wait_until(driver, selector):
    return driver.find_element(selector)
selector = sys.stdin.read().strip()
if selector == '__invalid__': selector = '[data-testid=missing]'
driver = Driver()
try:
    element = wait_until(driver, selector)
    element.click()
finally:
    driver.quit()
print(f'{driver.events[0]}|closed={driver.closed}')
